#include <cstdint>
#include "address.h"
#include "modules.h"

struct gen_aggressive_offset_s2_r1 : public champsim::modules::prefetcher {
    using prefetcher::prefetcher;

    static constexpr int REGION_SIZE = 16;
    static constexpr int OFFSET = 4;
    static constexpr int MAX_CONFIDENCE = 3;
    static constexpr int MIN_CONFIDENCE = 0;

    struct region_entry {
        champsim::block_number base;
        int confidence;
    };

    std::vector<region_entry> regions;

    uint32_t prefetcher_cache_operate(champsim::address addr, champsim::address ip,
                                     uint8_t cache_hit, bool useful_prefetch,
                                     access_type type, uint32_t metadata_in) {
        champsim::block_number blk{addr};
        champsim::block_number region_base{static_cast<int64_t>(blk) & ~(REGION_SIZE - 1)};

        for (auto &entry : regions) {
            if (entry.base == region_base) {
                if (entry.confidence > MIN_CONFIDENCE) {
                    prefetch_line(champsim::address{blk + OFFSET}, true, metadata_in);
                }
                return metadata_in;
            }
        }

        if (regions.size() < REGION_SIZE) {
            regions.push_back({region_base, MAX_CONFIDENCE});
        } else {
            regions[0] = {region_base, MAX_CONFIDENCE};
        }
        return metadata_in;
    }

    uint32_t prefetcher_cache_fill(champsim::address addr, long set, long way,
                                  uint8_t prefetch, champsim::address evicted_addr,
                                  uint32_t metadata_in) {
        champsim::block_number blk{addr};
        champsim::block_number region_base{static_cast<int64_t>(blk) & ~(REGION_SIZE - 1)};

        for (auto &entry : regions) {
            if (entry.base == region_base) {
                champsim::block_number pref_blk = blk + OFFSET;
                champsim::block_number evict_blk{evicted_addr};
                if (prefetch && evict_blk == pref_blk) {
                    entry.confidence = std::min(entry.confidence + 1, MAX_CONFIDENCE);
                } else if (!prefetch) {
                    entry.confidence = std::max(entry.confidence - 1, MIN_CONFIDENCE);
                }
                break;
            }
        }
        return metadata_in;
    }
};

